﻿.page {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: calc(100svh - 180px);
  padding: 32px 20px 48px;
  background: radial-gradient(ellipse at 50% 0%, #e9efe7 0%, transparent 65%), #f6f7f3;
  color: #243e33;
}
.panel {
  width: 100%;
  max-width: 460px;
  padding: 32px 26px 26px;
  border: 1px solid #e2e8de;
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 24px 64px -28px #183c302b, 0 4px 16px -8px #183c3012;
}
.brand { display: flex; justify-content: center; margin-bottom: 30px; color: #183c30; }
.brand a { display: inline-flex; border-radius: 4px; }
.eyebrow { margin: 0 0 12px; text-align: center; font-size: 10px; font-weight: 600; line-height: 1.5; letter-spacing: .18em; color: #687b6c; }
.heading { margin: 0; text-align: center; font-size: clamp(25px, 6vw, 30px); line-height: 1.2; font-weight: 600; letter-spacing: -.045em; color: #183c30; text-wrap: balance; }
.subtitle { max-width: 300px; margin: 12px auto 30px; text-align: center; font-size: 13px; line-height: 1.75; color: #66756b; text-wrap: balance; }
.form { display: flex; flex-direction: column; gap: 20px; }
.panel label { font-size: 12px; line-height: 20px; font-weight: 600; letter-spacing: 0; text-transform: none; color: #344d40; }
.panel input { width: 100%; min-height: 54px; border: 1px solid #dde4dc; border-radius: 12px; background: #fafbf8; padding: 14px 16px; font-size: 16px; line-height: 24px; color: #263b2d; transition: border-color 160ms, box-shadow 160ms, background-color 160ms; }
.panel input::placeholder { color: #828e83; font-weight: 400; font-size: 14px; }
.panel input:hover { border-color: #b6c5b9; }
.panel input:focus { outline: none; border-color: #52765e; background: #fff; box-shadow: 0 0 0 3px #52765e14; }
.panel button:focus-visible, .panel a:focus-visible { outline: 2px solid #52755a; outline-offset: 4px; }
.panel form label + button { color: #60745e; font-size: 11px; text-decoration: none; min-height: 28px; }
.panel form label + button:hover { color: #183c30; text-decoration: underline; text-underline-offset: 3px; }
.passwordField { position: relative; }
.passwordField input { padding-right: 48px; }
.passwordToggle { position: absolute; right: 5px; top: 5px; display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 8px; color: #7b8d7e; }
.passwordToggle:hover { color: #183c30; background: #edf2ea; }
.submit, .google { display: flex; justify-content: center; align-items: center; gap: 12px; width: 100%; min-height: 52px; border-radius: 12px; font-size: 13px; font-weight: 600; transition: background-color 160ms, border-color 160ms, box-shadow 160ms; }
.submit { position: relative; margin-top: 4px; background: linear-gradient(115deg, #234e3d, #163c2e); color: #fff; border: 1px solid #183c30; box-shadow: 0 5px 12px #183c301a, inset 0 1px 0 #ffffff12; }
.submit svg { position: absolute; right: 18px; }
.submit:hover:not(:disabled) { background: #2a5642; box-shadow: 0 6px 16px #183c3029; }
.submit:active:not(:disabled) { background: #143527; box-shadow: none; }
.divider { display: flex; align-items: center; gap: 14px; margin: 24px 0; color: #737f73; font-size: 11px; }
.divider > :first-child, .divider > :last-child { background: #e9ede6; }
.google { border: 1px solid #dde4dc; color: #354539; background: #fff; }
.google:hover:not(:disabled) { background: #f7f9f4; border-color: #b6c5b9; }
.submit:disabled, .google:disabled { opacity: .55; cursor: wait; }
.register { margin-top: 26px; padding: 18px 8px; border: 1px solid #edf0e8; border-radius: 12px; background: #f8faf6; text-align: center; font-size: 12px; line-height: 1.8; color: #66756b; }
.register a { display: inline-block; margin-left: 3px; color: #183c30; font-weight: 600; white-space: nowrap; }
.terms { margin: 22px auto 0; max-width: 320px; color: #717d71; font-size: 10px; line-height: 1.8; text-align: center; }
.terms a:hover { color: #183c30; }
.support { margin-top: 16px; text-align: center; font-size: 11px; color: #707e6f; }
.support a { color: #526c56; text-decoration: underline; text-underline-offset: 3px; }
@media (min-width: 640px) { .page { padding-block: 56px; } .panel { padding: 38px 38px 28px; } }
@media (max-width: 359px) { .page { padding: 20px 12px 32px; } .panel { padding: 28px 18px 22px; border-radius: 20px; } .panel form label + button { font-size: 10px; } }
@media (prefers-reduced-motion: reduce) { .panel input, .submit, .google { transition: none; } }
.googleHint { margin: 10px auto 0; max-width: 300px; text-align: center; color: #697b6d; font-size: 11px; line-height: 1.7; }
.returnOverlay { position: fixed; inset: 0; z-index: 10000; overflow-y: auto; align-items: center; }
.returnEmblem { display: flex; align-items: center; justify-content: center; width: 64px; height: 64px; margin: 24px auto; border: 1px solid #dce7d9; border-radius: 50%; background: #f2f7ee; color: #315e43; font-size: 26px; }
.spinner, .smallSpinner { display: inline-block; width: 24px; height: 24px; border: 2px solid #cbdac8; border-top-color: #315e43; border-radius: 50%; animation: authSpin .85s linear infinite; }
.smallSpinner { width: 14px; height: 14px; flex-shrink: 0; }
.authSteps { display: flex; flex-direction: column; gap: 18px; margin: 28px 0; padding: 22px; border: 1px solid #e7ede2; border-radius: 14px; background: #fafcf8; list-style: none; }
.authSteps li { display: flex; align-items: center; gap: 12px; font-size: 12px; color: #687969; }
.authSteps li[aria-current] { color: #183c30; font-weight: 600; }
.authSteps li span { display: flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 50%; border: 1px solid #dce5d6; background: #fff; font-size: 11px; }
.authSteps li[aria-current] span { background: #183c30; border-color: #183c30; color: #fff; }
@keyframes authSpin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner, .smallSpinner { animation: none; } }
@media (max-height: 650px) { .returnOverlay { align-items: flex-start; } }
